mapper.select:
SELECT ptp.person_id AS personId, u.username AS personUsername FROM person_temp_permission ptp INNER JOIN user u ON u.id = ptp.person_id
AND u.status = #{status}
AND ptp.person_id = #{personId}
GROUP BY ptp.person_id, u.username ORDER BY MAX(ptp.updated_time) DESC

SELECT ptp.person_id AS personId, a.username AS personUsername FROM person_temp_permission ptp INNER JOIN admin a ON a.id = ptp.person_id
AND a.status = #{status}
AND ptp.person_id = #{personId}
GROUP BY ptp.person_id, a.username ORDER BY MAX(ptp.updated_time) DESC

SELECT ptp.id, ptp.person_id AS personId, ptp.permission_id AS permissionId, p.perms, p.name AS permissionName, p.group_name AS groupName, ptp.start_time AS startTime, ptp.expire_time AS expireTime, ptp.status, ptp.grant_reason AS grantReason, ptp.grant_user_id AS grantUserId, ptp.created_time AS createdTime, u.username AS personUsername, gu.username AS grantUsername FROM person_temp_permission ptp LEFT JOIN permission p ON p.id = ptp.permission_id LEFT JOIN user u ON u.id = ptp.person_id LEFT JOIN user gu ON gu.id = ptp.grant_user_id WHERE ptp.person_id = #{personId}
AND ptp.status = #{status}
ORDER BY ptp.created_time DESC

SELECT ptp.id, ptp.person_id AS personId, ptp.permission_id AS permissionId, p.perms, p.name AS permissionName, p.group_name AS groupName, ptp.start_time AS startTime, ptp.expire_time AS expireTime, ptp.status, ptp.grant_reason AS grantReason, ptp.grant_user_id AS grantUserId, ptp.created_time AS createdTime, a.username AS personUsername, ga.username AS grantUsername FROM person_temp_permission ptp LEFT JOIN permission p ON p.id = ptp.permission_id LEFT JOIN admin a ON a.id = ptp.person_id LEFT JOIN admin ga ON ga.id = ptp.grant_user_id WHERE ptp.person_id = #{personId}
AND ptp.status = #{status}
ORDER BY ptp.created_time DESC
